mapper.select:
select o.family_id familyId, f.name familyName, f.user_id familyUserId, f.nick_name familyNickName, SUM(o.live_time_sec) as alltime, sum(o.ticket) as allticket, sum(o.cp_cost) as allCpCost, sum(o.cp_prize) as allPrize, SUBSTR(o.create_time,1,10) as shijian, #{countTime} timedata from ${dbLive}.live_host_wage_note o left join ${dbLive}.live_family f on o.family_id=f.id
and o.family_id = #{dto.familyId} and f.name like concat('%',#{dto.familyName},'%') and f.nick_name like concat('%',#{dto.familyNickName},'%') and o.create_time >= #{dto.startTime} and o.create_time <= #{dto.endTime}
group by o.family_id order by o.family_id asc

select o.family_id familyId, f.name familyName, f.user_id familyUserId, f.nick_name familyNickName, o.host_id hostId, u.nick_name nickName, SUM(o.live_time_sec) as alltime, sum(o.ticket) as allticket, sum(o.cp_cost) as allCpCost, sum(o.cp_prize) as allPrize, SUBSTR(o.create_time,1,10) as shijian, #{countTime} timedata from ${dbLive}.live_host_wage_note o left join ${dbLive}.live_family f on o.family_id=f.id left join ${dbLive}.live_user u on o.host_id=u.id
and o.family_id = #{dto.familyId} and o.host_id = #{dto.hostId} and u.nick_name like concat('%',#{dto.nickName},'%') and o.create_time >= #{dto.startTime} and o.create_time <= #{dto.endTime}
group by o.host_id order by o.create_time desc
